import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Обзор Memoh","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/overview.md","filePath":"ru/guides/overview.md","lastUpdated":1792323081000}'),l={name:"ru/guides/overview.md"};function h(i,e,s,n,m,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="обзор-memoh" tabindex="-1">Обзор Memoh <a class="header-anchor" href="#обзор-memoh" aria-label="Permalink to &quot;Обзор Memoh&quot;">​</a></h1><p>Memoh даёт каждому Bot собственный облачный компьютер: рабочее пространство с настоящей файловой системой и терминалом, браузер на рабочем столе, за которым можно наблюдать и который можно перехватывать, и долговременную память, которая переносится между сессиями. Закройте ноутбук — Bot продолжит работать.</p><p>С Bot работают, отправляя ему сообщения — в приложении Memoh или в Telegram, Slack, Discord, Feishu, DingTalk, WeCom, WeChat, QQ и LINE. Любая точка входа ведёт к одному и тому же Bot и одной и той же памяти.</p><p>Для начала достаточно скачать приложение и войти в Memoh Cloud. Размещённые модели (DeepSeek, Kimi, GPT, Claude и другие) готовы к работе; чтобы использовать собственные ключи или свой сервис моделей, см. <a href="./quick-start.html#собственные-модели-byok">BYOK</a>.</p><h2 id="чем-memoh-отличается" tabindex="-1">Чем Memoh отличается <a class="header-anchor" href="#чем-memoh-отличается" aria-label="Permalink to &quot;Чем Memoh отличается&quot;">​</a></h2><ul><li><strong>Настоящий компьютер, а не одноразовая песочница.</strong> Записанные файлы и установленные рантаймы остаются в <a href="./container.html">рабочем пространстве</a>; то, что вы настроили в понедельник, в пятницу всё ещё на месте.</li><li><strong>Экран, который вы видите.</strong> Bot управляет настоящим браузером на видимом рабочем столе; когда он упирается в форму входа или CAPTCHA, вы <a href="./browser-computer-use.html">берёте клавиатуру на себя</a>, завершаете шаг и возвращаете управление.</li><li><strong>Он помнит.</strong> <a href="./memory.html">Долговременная память</a> действует между сессиями и каналами; предпочтение, исправленное один раз, должно закрепиться.</li><li><strong>Он работает, пока вас нет.</strong> <a href="./schedule.html">Задачи по расписанию</a> срабатывают по cron и доставляют результат в подключённые каналы — проверяют вовремя и говорят, только когда что-то изменилось.</li><li><strong>Подключайте собственного агента для программирования.</strong> Поместите Claude Code или Codex в то же рабочее пространство через <a href="./acp.html">ACP</a> — на вашей собственной подписке.</li></ul><h2 id="один-bot-—-одна-задача" tabindex="-1">Один Bot — одна задача <a class="header-anchor" href="#один-bot-—-одна-задача" aria-label="Permalink to &quot;Один Bot — одна задача&quot;">​</a></h2><p>У каждого Bot свои рабочее пространство, память, каналы и граница прав; Bot не видят друг друга. Когда работа действительно распадается на роли, создайте ещё один Bot вместо того, чтобы перегружать один. Кто может общаться с Bot, читать и записывать его файлы, выполнять команды — выдаётся уровень за уровнем в <a href="./access.html">Контроле доступа</a>: дайте уровень, которого требует задача, и не больше.</p><h2 id="хорошее-первое-поручение" tabindex="-1">Хорошее первое поручение <a class="header-anchor" href="#хорошее-первое-поручение" aria-label="Permalink to &quot;Хорошее первое поручение&quot;">​</a></h2><p>Выберите что-то небольшое, что вы и так каждую неделю делаете вручную, и сформулируйте результат, источники и границы:</p><blockquote><p>Каждую пятницу в 17:00 превращай ссылки и файлы, которые я отправил тебе за неделю, в еженедельный отчёт — сгруппированный по темам, по одной строке на пункт. Сохраняй его в рабочем пространстве, а сводку публикуй в этот диалог. Организуй только то, что я тебе отправил; никогда ничего никому не пересылай.</p></blockquote><p>Bot сам зарегистрирует расписание и будет доставлять отчёт каждую неделю. Начните с работы только на чтение, просмотрите несколько результатов, затем расширяйте то, что ему можно записывать и выполнять.</p><h2 id="частые-вопросы" tabindex="-1">Частые вопросы <a class="header-anchor" href="#частые-вопросы" aria-label="Permalink to &quot;Частые вопросы&quot;">​</a></h2><p><strong>Он продолжает работать, когда мой компьютер выключен?</strong></p><p>Да. Bot работает в облачном рабочем пространстве; расписания срабатывают, а сообщения в каналах получают ответы в любом случае.</p><p><strong>Сколько Bot я могу создать?</strong></p><p>Это зависит от вашего тарифа. Каждый Bot независим — собственные рабочее пространство, память и права — и удаление одного не влияет на остальные.</p><p><strong>Где лежат мои файлы?</strong></p><p>В изолированном контейнерном рабочем пространстве этого Bot (<code>/data</code>); они сохраняются между сессиями, и их можно просматривать в разделе <a href="./files.html">Файлы</a>.</p><p><strong>Могу ли я использовать собственные модели?</strong></p><p>Да. Добавьте свои API-ключи в разделе Providers (см. <a href="./quick-start.html#собственные-модели-byok">BYOK</a>); для агентов для программирования войдите со своей подпиской Claude Code или Codex на вкладке <strong>Agent</strong> нужного Bot.</p><p><strong>Куда идти с вопросами о тарифах и оплате?</strong></p><p>В <a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Центр помощи</a>: тарифы, кредиты, вопросы по аккаунту и прямая связь с командой Memoh.</p><h2 id="следующие-шаги" tabindex="-1">Следующие шаги <a class="header-anchor" href="#следующие-шаги" aria-label="Permalink to &quot;Следующие шаги&quot;">​</a></h2><ul><li><a href="./quick-start.html">Быстрый старт</a> — от установки приложения до подключённой чат-платформы примерно за пятнадцать минут.</li><li><a href="./working-with-bots.html">Bot</a> — настройте Bot вкладка за вкладкой.</li><li><a href="./../integrations/channels/">Каналы</a> — инструкции по настройке для каждой платформы.</li><li><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Центр помощи</a> — тарифы, оплата и вопросы по аккаунту.</li></ul>',25)])])}const u=a(l,[["render",h]]);export{c as __pageData,u as default};
